import {
      createServer,
        type IncomingMessage,
          type ServerResponse,
          } from "node:http";
          import type { Transaction } from "../core/types.js";
          import { Node } from "./node.js";

          const blockchainNode = new Node();

          function sendJson(
            response: ServerResponse,
              statusCode: number,
                data: unknown,
                ): void {
                  response.statusCode = statusCode;
                    response.setHeader("Content-Type", "application/json");
                      response.end(
                          JSON.stringify(data, (_, value) =>
                                typeof value === "bigint" ? value.toString() : value,
                                    ),
                                      );
                                      }

                                      async function readBody(
                                        request: IncomingMessage,
                                        ): Promise<string> {
                                          const chunks: Buffer[] = [];

                                            for await (const chunk of request) {
                                                chunks.push(
                                                      Buffer.isBuffer(chunk)
                                                              ? chunk
                                                                      : Buffer.from(chunk),
                                                                          );
                                                                            }

                                                                              return Buffer.concat(chunks).toString("utf8");
                                                                              }

                                                                              function parseTransaction(
                                                                                value: unknown,
                                                                                ): Transaction | null {
                                                                                  if (
                                                                                      typeof value !== "object" ||
                                                                                          value === null
                                                                                            ) {
                                                                                                return null;
                                                                                                  }

                                                                                                    const input = value as Record<string, unknown>;

                                                                                                      if (
                                                                                                          typeof input.id !== "string" ||
                                                                                                              typeof input.from !== "string" ||
                                                                                                                  typeof input.to !== "string" ||
                                                                                                                      typeof input.amount !== "string" ||
                                                                                                                          typeof input.fee !== "string" ||
                                                                                                                              typeof input.timestamp !== "number" ||
                                                                                                                                  typeof input.publicKey !== "string" ||
                                                                                                                                      typeof input.signature !== "string"
                                                                                                                                        ) {
                                                                                                                                            return null;
                                                                                                                                              }

                                                                                                                                                try {
                                                                                                                                                    return {
                                                                                                                                                          id: input.id,
                                                                                                                                                                from: input.from,
                                                                                                                                                                      to: input.to,
                                                                                                                                                                            amount: BigInt(input.amount),
                                                                                                                                                                                  fee: BigInt(input.fee),
                                                                                                                                                                                        timestamp: input.timestamp,
                                                                                                                                                                                              publicKey: input.publicKey,
                                                                                                                                                                                                    signature: input.signature,
                                                                                                                                                                                                        };
                                                                                                                                                                                                          } catch {
                                                                                                                                                                                                              return null;
                                                                                                                                                                                                                }
                                                                                                                                                                                                                }

                                                                                                                                                                                                                function getMinerAddress(
                                                                                                                                                                                                                  value: unknown,
                                                                                                                                                                                                                  ): string | null {
                                                                                                                                                                                                                    if (
                                                                                                                                                                                                                        typeof value !== "object" ||
                                                                                                                                                                                                                            value === null
                                                                                                                                                                                                                              ) {
                                                                                                                                                                                                                                  return null;
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                      const input = value as Record<string, unknown>;

                                                                                                                                                                                                                                        if (typeof input.minerAddress !== "string") {
                                                                                                                                                                                                                                            return null;
                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                if (input.minerAddress.length === 0) {
                                                                                                                                                                                                                                                    return null;
                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                        return input.minerAddress;
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        const server = createServer(
                                                                                                                                                                                                                                                          async (
                                                                                                                                                                                                                                                              request: IncomingMessage,
                                                                                                                                                                                                                                                                  response: ServerResponse,
                                                                                                                                                                                                                                                                    ) => {
                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                              const method = request.method ?? "GET";
                                                                                                                                                                                                                                                                                    const url = new URL(
                                                                                                                                                                                                                                                                                            request.url ?? "/",
                                                                                                                                                                                                                                                                                                    "http://localhost",
                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                        method === "GET" &&
                                                                                                                                                                                                                                                                                                                                url.pathname === "/health"
                                                                                                                                                                                                                                                                                                                                      ) {
                                                                                                                                                                                                                                                                                                                                              sendJson(response, 200, {
                                                                                                                                                                                                                                                                                                                                                        status: "ok",
                                                                                                                                                                                                                                                                                                                                                                  valid: blockchainNode.isValid(),
                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                              if (
                                                                                                                                                                                                                                                                                                                                                                                                      method === "GET" &&
                                                                                                                                                                                                                                                                                                                                                                                                              url.pathname === "/transactions"
                                                                                                                                                                                                                                                                                                                                                                                                                    ) {
                                                                                                                                                                                                                                                                                                                                                                                                                            sendJson(response, 200, {
                                                                                                                                                                                                                                                                                                                                                                                                                                      transactions:
                                                                                                                                                                                                                                                                                                                                                                                                                                                  blockchainNode.getPendingTransactions(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      method === "GET" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              url.pathname === "/blocks"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sendJson(response, 200, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      blocks: blockchainNode.getBlocks(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          method === "GET" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  url.pathname === "/balance"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const address = url.searchParams.get("address");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!address) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sendJson(response, 400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error: "address is required",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sendJson(response, 200, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            address,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      balance: blockchainNode
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .getBalance(address)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .toString(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  method === "POST" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          url.pathname === "/transactions"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const body = await readBody(request);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let parsed: unknown;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  parsed = JSON.parse(body);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sendJson(response, 400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                error: "Invalid JSON",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const transaction = parseTransaction(parsed);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (transaction === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      sendJson(response, 400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error: "Invalid transaction format",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const accepted =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                blockchainNode.submitTransaction(transaction);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!accepted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sendJson(response, 400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              accepted: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          error: "Transaction rejected",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              sendJson(response, 201, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        accepted: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  transaction,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      method === "POST" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              url.pathname === "/mine"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const body = await readBody(request);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let parsed: unknown = {};

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (body.trim().length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  parsed = JSON.parse(body);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendJson(response, 400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: "Invalid JSON",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const minerAddress = getMinerAddress(parsed);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (minerAddress === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sendJson(response, 400, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: "minerAddress is required",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const block = blockchainNode.mine(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    minerAddress,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sendJson(response, 201, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              block,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sendJson(response, 404, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error: "Route not found",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sendJson(response, 500, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          error: "Internal server error",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const port = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        process.env.PORT ?? 3000,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );



export { server, port };

export function startServer(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (server.listening) {
      resolve();
      return;
    }

    server.once("error", reject);

    server.listen(port, () => {
      console.log(`Noppay Chain node listening on port ${port}`);
      resolve();
    });
  });
}

export function stopServer(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (!server.listening) {
      resolve();
      return;
    }

    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}
